  'settings.torrents.portMapNeedsPort': 'حدد منفذًا أعلاه قبل توجيهه - عند 0 لا يجد الموجّه ما يوجهه إليه.',
  'settings.torrents.portMapConfirmed': 'تم التأكيد: المنفذ {port} موجَّه وتم التحقق من إمكانية الوصول إليه.',
  'settings.torrents.portMapUnconfirmed': 'قبل الموجّه الطلب، لكن تعذّر التأكد من أن التوجيه يعمل فعليًا. بعض الموجّهات تفعل هذا بصمت - جرّب فحص الاتصال من خارج الشبكة.',
  'settings.torrents.portMapFailed': 'تعذّر توجيه المنفذ: {error}',
