  'settings.torrents.networkTitle': 'اكتشاف الأقران',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'يجد أقرانًا دون أي متعقب، باستخدام عملاء BitTorrent آخرين كدليل موزّع.',
  'settings.torrents.pex': 'تبادل الأقران (PEX)',
  'settings.torrents.pexHint': 'يتبادل الأقران المعروفين مع المتصلين بالفعل، بحيث يوجد السرب ذو الأقران القليلين بسرعة أكبر.',
  'settings.torrents.privateNote': 'يعطّل التورنت الخاص كلتا الميزتين تلقائيًا بمجرد معرفة بياناته الوصفية، بغض النظر عن الإعداد هنا - فورًا في حالة رفع ملف .torrent، أو بمجرد وصول البيانات الوصفية الخاصة برابط المغناطيس من السرب. يحظر معظم المتعقبات الخاصة الحسابات التي تستخدم أيًا منهما.',
  'settings.torrents.engineNote': 'أصبحت نسبة البذر المستهدفة ومدة البذر المستهدفة والمنفذ تصل الآن إلى كل تورنت يبدأه هذا المحرك - أما المنفذ فلا يسري إلا على أول تورنت منذ آخر إعادة تشغيل لهذه النسخة فقط، لأن عميل BitTorrent الخاص بالمحرك يُبنى مرة واحدة فقط ولا يُعاد بناؤه بعد ذلك؛ ومع ذلك يُخزَّن أي حفظ لاحق بشكل صحيح ويصبح ساري المفعول اعتبارًا من إعادة التشغيل التالية. أما حد الرفع فلا يزال يُحفظ ويُتحقق منه فقط، إذ لا توجد بعد وسيلة لدى المحرك لتطبيقه على تنزيل جارٍ. وينطبق الأمر نفسه على DHT وPEX أدناه في حالة تورنت عادي (غير خاص): الإعداد الافتراضي لهذه النسخة لا يصل هو الآخر بعد إلى تنزيل جارٍ، لذا يستمر التورنت في البذر وكلاهما مفعّل بغض النظر عن الإعداد هنا - أما التورنت الخاص فحالة مختلفة تمامًا، انظر الملاحظة أدناه. ومع ذلك، يقوم زر التوجيه أدناه بشيء حقيقي: يطلب بصدق من الموجّه توجيه رقم المنفذ المُدخل أعلاه، سواء كان هناك تورنت ينصت عليه الآن أم لا.',
