  'onboarding.finish': 'ابدأ استخدام KnightLoader',
  'onboarding.welcome.title': 'مرحبًا بك في KnightLoader',
  'onboarding.welcome.body': 'KnightLoader مدير تنزيلات ذاتي الاستضافة: الصق رابطًا أو أسقطه ليُجلَب عبر أي واجهة خلفية تتولى أمره فعليًا - المحرك المدمج للروابط المباشرة، وyt-dlp لصفحات الوسائط، وخدمة ديبريد للمضيفين الذين تدفع لهم بالفعل، أو JDownloader بلا واجهة رسومية لكل ما عدا ذلك. تغطي هذه الجولة القصيرة الإعداد الوحيد الذي يستحق التحقق منه قبل أن تبدأ.',
  'onboarding.welcome.langLabel': 'لغة الواجهة',
  'onboarding.folder.title': 'أين يجب أن تحطّ الملفات؟',
  'onboarding.folder.body': 'هذا هو المجلد الذي تُكتب فيه التنزيلات المكتملة. اكتب مسارًا أو تصفّح الخادم لاختيار واحد - يمكنك تغييره مرة أخرى في أي وقت من صفحة الإعدادات العامة.',
  'onboarding.accounts.title': 'مضيفون مميّزون، متى ما أردتهم',
  'onboarding.accounts.body': 'يعمل الطابور بلا أي حساب على الإطلاق. وعندما ترغب في السرعة الكاملة على مضيف أو خدمة ديبريد تدفع لها بالفعل، أضِف بيانات الدخول إليها تحت الحسابات - لا حاجة لإعداد أي شيء هنا الآن.',
  'onboarding.accounts.link': 'فتح الحسابات',
  'onboarding.finished.title': 'أنت جاهز الآن',
  'onboarding.finished.body': 'بهذا تنتهي الجولة. تحتوي صفحة المساعدة تحت الإعدادات على شرح كامل لكل شيء آخر يقوم به هذا الإصدار، وتحمل معظم عناصر التحكم شرحها الخاص خلف أيقونة (i).',

