  'settings.rules.notFound': 'لا توجد هنا قاعدة اسمها «{name}». أُعيدت تسميتها أو حُذفت بعد إضافة الرابط الذي يذكرها.',

  'notifications.title': 'الإشعارات',
  'notifications.titleHint': 'قرّر لكل حدث على حدة: أيظهر فقاعةً داخل التطبيق، أم إشعارًا من نظام تشغيلك، أم لا يظهر أصلًا. وإشعار النظام لا يصلك إلا ما دام تبويب KnightLoader مفتوحًا، والوضع الصامت أدناه يسري فوق هذا كله.',
  'notifications.channel.app': 'داخل التطبيق',
  'notifications.channel.system': 'إشعار النظام',
  'notifications.channel.silent': 'لا تُظهر شيئًا',
  'notifications.event.downloadDone': 'اكتمال تنزيل',
  'notifications.event.downloadDoneHint': 'كل تنزيل يبلغ نهايته يقول ذلك. ومئتا ملف في الطابور تعني مئتي إشعار، ففكّر مرتين قبل أن ترسلها إلى النظام.',
  'notifications.event.downloadFailed': 'فشل تنزيل',
  'notifications.event.downloadFailedHint': 'تنزيل استسلم. والوضع الصامت لا يخفي هذا أبدًا.',
