  'notifications.event.extractionDoneHint': 'أرشيف انتهى فكّ ضغطه. لم يكن هذا يُبلَّغ عنه في أي مكان من قبل، ولذلك يبدأ على «لا تُظهر شيئًا».',
  'notifications.event.extractionFailed': 'فشل فك الضغط',
  'notifications.event.extractionFailedHint': 'أرشيف توقّف قبل أن يكتمل. والسبب المعتاد كلمة مرور ناقصة، وتبقى الملفات مكانها حتى تتصرّف.',
  'notifications.event.captchaWaiting': 'كابتشا تنتظر',
  'notifications.event.captchaWaitingHint': 'نافذة الكابتشا تُفتح في هذا التبويب على أي حال. وهي تبدأ على «لا تُظهر شيئًا» لأن تلك النافذة هي الرسالة نفسها ما دمت تنظر إليها. اضبطها على إشعار النظام، فتصلك كابتشا في تبويب خلفي قبل أن يرمي المستضيف الجلسة.',
  'notifications.event.captchaFailed': 'فشل الكابتشا',
  'notifications.event.captchaFailedHint': 'لم يجب أحد في الوقت المتاح، أو لم تصل الإجابة. والتنزيل الذي وراءها يبقى مكانه.',
  'notifications.event.captchaResolved': 'أُجيبت الكابتشا في مكان آخر',
  'notifications.event.captchaResolvedHint': 'أجاب عنها أحدهم في متصفّح آخر، أو حلّال آلي، فأُغلقت النافذة من تلقاء نفسها.',
  'notifications.systemUnavailable': 'إشعارات النظام غير متاحة هنا: متصفّحك لا يقدّمها إلا عبر HTTPS أو على localhost. وكل ما في هذه البطاقة يظل يظهر داخل التطبيق رغم ذلك.',
  'notifications.systemBlocked': 'متصفّحك يحجب الإشعارات لهذا العنوان. والصفوف المضبوطة على «إشعار النظام» تظهر داخل التطبيق بدلًا من ذلك، حتى تسمح بها من جديد في إعدادات المواقع في متصفّحك.',
  'notifications.systemNotGranted': 'المتصفّح لم يمنح الإذن، فيبقى هذا الحدث داخل التطبيق. اختر «إشعار النظام» مرة أخرى كي يُسأل من جديد.',
  'notifications.test': 'أرسل اختبارًا',
