  'views.full': 'لديك {n} عرض محفوظ، وهذا كل ما تحتفظ به هذه القائمة. احذف واحدًا ليتّسع مكان لآخر.',
  'views.tooBig': 'هذا العرض يحوي من قيم المرشّحات أكثر مما يمكن تخزينه. أزل بعض العلامات في الشريط الجانبي واحفظه من جديد.',
  'views.manage': 'إدارة العروض المحفوظة',
