  'select.reduced': 'أُخرج {n} صف من التحديد.',
  'remove.doneHidden': 'أُزيل {n} تنزيل. {hidden} منها لم ترها.',
  'settings.dbmaint.title': 'صيانة قاعدة البيانات',
  'settings.dbmaint.hint': 'قائمة المهام وسجل التنزيلات وحالة الواجهة تقيم كلها في ملف SQLite واحد. والصفوف المحذوفة تحرّر مساحة داخل الملف، لكنها لا تعيدها إلى القرص أبدًا، فبعد بضع سنوات يصير الملف أضعاف ما فيه. والفحص يقرأ كل صفحة ويقول إن كان الملف ما زال سليمًا. والرصّ يعيد كتابته على حجمه الحقيقي. وكلاهما يعمل على قاعدة البيانات وهي قيد التشغيل، ويحبس كل كتابة أخرى ما دام يعمل.',
  'settings.dbmaint.storeSize': 'ملف قاعدة البيانات',
  'settings.dbmaint.storeSizeHint': 'قاعدة البيانات، ومعها ملف يومية بجوارها إن كان SQLite يُبقي واحدًا مفتوحًا الآن.',
  'settings.dbmaint.reclaimable': 'مساحة حرة داخل الملف',
  'settings.dbmaint.reclaimableHint': 'مساحة خلّفتها الصفوف المحذوفة. وهي ما زالت جزءًا من الملف على القرص، ولا يعيدها إلا الرصّ. والرقم حدّ أدنى: الرصّ يعيد أيضًا حزم الصفحات نصف الممتلئة، فيعود عادةً أكثر من هذا.',
  'settings.dbmaint.settingsSize': 'settings.json',
  'settings.dbmaint.settingsMissing': 'لم يُكتب بعد',
  'settings.dbmaint.settingsMissingHint': 'لا يُكتب هذا الملف إلا حين تحفظ صفحة إعدادات لأول مرة. وحتى ذلك الحين تعمل النسخة على الإعدادات الافتراضية المدمجة.',
  'settings.dbmaint.inBundle': 'هذه الأحجام موجودة في حزمة التشخيص أيضًا. أما المسارات فلا: الحزمة يُفترض أن تُرفَق بتقرير خطأ علني.',
  'settings.dbmaint.check': 'فحص السلامة',
  'settings.dbmaint.checkHint': 'يقرأ كل صفحة من قاعدة البيانات ويبلّغ بما يجده SQLite. وهو يقرأ فقط ولا يغيّر شيئًا. وعلى ملف كبير يستغرق وقتًا، وما دام يعمل لا يستطيع شيء آخر أن يكتب في قاعدة البيانات.',
  'settings.dbmaint.compact': 'رصّ الملف',
  'settings.dbmaint.compactHint': 'يعيد كتابة الملف كله على حجمه الحقيقي. وهو يحتاج مساحة لنسخة ثانية كاملة من قاعدة البيانات، وتُكتب هذه النسخة في المجلد المؤقت، لا في مجلد البيانات.',
  'settings.dbmaint.analyze': 'تجديد إحصاءات الاستعلامات',
  'settings.dbmaint.analyzeHint': 'يدع SQLite يقيس الجداول من جديد ليختار خططًا أفضل لاستعلامات القائمة والسجل. وهذا سريع ولا يغيّر أي بيانات. والاستعلامات التي حُضّرت قبل هذه اللحظة تحتفظ بخطتها القديمة، فالأثر كامل بعد إعادة التشغيل التالية على أبعد تقدير.',
  'settings.dbmaint.running': 'جارٍ التنفيذ…',
  'settings.dbmaint.busy': 'هناك شيء يعمل بالفعل. انتظر حتى ينتهي.',
  'settings.dbmaint.neverRun': 'لم يعمل شيء على هذه النسخة بعد.',
  'settings.dbmaint.lastRun': 'آخر تشغيل {when}، واستغرق {seconds} ثانية.',
  'settings.dbmaint.checkOk': 'سليمة. قرأ SQLite كل صفحة ولم يجد خللًا.',
  'settings.dbmaint.checkFailed': 'تالفة. يبلّغ SQLite عن {n} مشكلة.',
  'settings.dbmaint.checkFailedHelp': 'لا تُعِد تشغيل الخادم. فهو لا يبدأ أصلًا على قاعدة بيانات لا يستطيع فتحها، والحاوية المضبوطة على إعادة تشغيل نفسها تظل تدور في حلقة عندئذٍ. جرّب أولًا زر التنزيل تحت «النسخ الاحتياطي والاستعادة» وضع الملف في مكان آمن؛ وعلى قاعدة بيانات تالفة بشدة قد يفشل هذا أيضًا. فإن فشل، أوقف الخادم وانسخ {path} جانبًا بيدك قبل أن يمسّه أي شيء آخر، ثم أعِد آخر نسخة احتياطية سليمة عبر «الاستعادة».',
  'settings.dbmaint.compacted': '{before} قبل الرصّ، و{after} بعده. عاد {freed} إلى القرص.',
  'settings.dbmaint.compactedNothing': '{before} قبل الرصّ وبعده. لم يكن هناك ما يُعاد.',
  'settings.dbmaint.analyzed': 'تجدّدت الإحصاءات.',
  'settings.dbmaint.failed': 'لم يكتمل: {error}',
  'settings.dbmaint.diskFullHelp': 'الرصّ يكتب نسخة ثانية كاملة من قاعدة البيانات قبل أن يستبدل الأصل، ويكتب تلك النسخة في المجلد المؤقت، لا في مجلد البيانات. وهو هنا {tmp}، وفيه {free} حرة. وجّه TMPDIR إلى مجلد على القرص نفسه الذي يقع عليه مجلد بياناتك، وحاول من جديد.',
  'settings.dbmaint.skippedBusy': 'لم يجرِ التشغيل المجدول لأن تنزيلات كانت تعمل.',
  'settings.dbmaint.interval': 'التشغيل من تلقاء نفسه',
  'settings.dbmaint.intervalHint': 'مطفأ على تثبيت قائم، ويبقى مطفأً بعد التحديث: لا يبدأ شيء بنفسه لمجرد أنك ثبّت إصدارًا جديدًا. وحين تشغّله، يقع أول تشغيل بعد فترة كاملة، لا الآن. وإن كان هناك تنزيل يعمل في ذلك الوقت، سقط التشغيل ولم يقف في الطابور.',
  'settings.dbmaint.intervalNever': 'عند الضغط على الزر فقط',
