  'settings.dbmaint.compactOnSchedule': 'رصّ الملف في التشغيل المجدول أيضًا',
  'settings.dbmaint.compactOnScheduleHint': 'الإطفاء يعني أن التشغيل المجدول يقرأ ويبلّغ فقط. والرصّ يعيد كتابة الملف كله ويحتاج مساحة لنسخة ثانية منه على قرص المجلد المؤقت، فلا تشغّله دون أن تعرف أن تلك المساحة موجودة. وزر الرصّ في الأعلى يرصّ دائمًا حين تضغطه، مهما كان المكتوب هنا.',
  'settings.dbmaint.confirmTitle': 'رصّ قاعدة البيانات؟',
