  'overview.speedWindow.minute': 'الدقيقة الأخيرة',
  'overview.speedWindow.hour': 'الساعة الأخيرة',
  'overview.speedGraphHint': 'النسخة تسجّل هذا المنحنى بنفسها: قيمة كل ثانية للدقيقتين الأخيرتين، وقيمة كل عشر ثوانٍ للساعة الأخيرة. ولهذا يظهر ممتلئًا بعد إعادة تحميل الصفحة بدل أن يبدأ مسطحًا. والتسجيل يقيم في الذاكرة فقط: إن أعدت تشغيل KnightLoader صار فارغًا، ويبدأ المنحنى خطًا مسطحًا من جديد ويمتلئ مع مرور الوقت.',
  'settings.diagnostics.speedSamples': 'قيم السرعة المسجّلة',
  'settings.diagnostics.speedSamplesHint': 'من كم قيمة يُرسم منحنى السرعة في صفحة النظرة العامة الآن، قياسًا إلى أقصى ما يحتفظ به: أولًا تسجيل الدقيقتين، ثم تسجيل الساعة. والصفر في كليهما يعني أن شيئًا لا يسجّل، وأن المنحنى في النظرة العامة سيبقى مسطحًا حتى يُصلَح ذلك. والتسجيل يبدأ فارغًا بعد كل إعادة تشغيل، ولا يُكتب على القرص أبدًا.',
  'settings.downloads.idleActionQuit': 'إنهاء KnightLoader',
  'settings.downloads.idleActionCommand': 'تنفيذ أمر',
  'settings.downloads.idleActionSuspend': 'إنامة هذا الجهاز',
  'settings.downloads.idleDeploymentContainer': 'هذا يعمل داخل حاوية. وعمليته هي PID 1 داخل فضاء أسمائها الخاص: الإنهاء يوقف الحاوية ولا شيء غير ذلك، ولا يستطيع إنامة الجهاز الذي تحتها، لأن حالة الطاقة في ذلك الجهاز ليست شيئًا يصل إليه أي شيء من داخل الحاوية. وما إذا كانت الحاوية ستعود بعد الإنهاء تقرره سياسة إعادة التشغيل التي أعطيتها إياها، لا هذا الإعداد. وإن أردت إنامة المضيف، فاستخدم هنا أمرًا يصل إلى المضيف.',
  'settings.downloads.idleDeploymentDesktop': 'هذا هو إصدار سطح المكتب، ولذلك يستطيع إنامة هذا الجهاز. والإنهاء غير مطروح هنا، لأن النافذة وأيقونة شريط النظام تغلقان التطبيق بالطريقة النظيفة أصلًا.',
  'settings.downloads.idleQuitHint': 'الإنهاء يترك العمل الجاري ينتهي ثم يوقف العملية، تمامًا كزر الخروج في صفحة متقدم. وما إذا كان سيبدأ من جديد بعد ذلك تقرره سياسة إعادة التشغيل الخاصة بحاويتك، لا هذا الإعداد.',
  'settings.downloads.idleSuspendHint': 'الإنامة تطلب من نظام التشغيل أن يضع هذا الجهاز في وضع توفير الطاقة. وهي لا تنجح إلا حيث يسمح النظام لهذا التطبيق بالطلب: على لينكس قد ترفض إدارة الصلاحيات، وعندئذٍ يُكتب السبب تحت آخر تشغيل.',
  'settings.downloads.idleCommandProgram': 'البرنامج',
  'settings.downloads.idleCommandProgramHint': 'المسار الكامل للبرنامج الذي يُشغَّل. وهو يعمل مباشرةً لا عبر صدفة، ولذلك فإن الأنبوب أو إعادة التوجيه أو أمرين متتاليين مكانها ملف سكربت تشير إليه من هنا. ولا يُستبدل فيه شيء: ما تكتبه هنا هو ما يعمل بالضبط.',
  'settings.downloads.idleCommandArgs': 'الوسيطات',
  'settings.downloads.idleCommandArgsHint': 'واحدة في كل سطر، حتى تبقى الوسيطة التي فيها مسافة وسيطة واحدة.',
  'settings.downloads.idleCommandTimeout': 'إيقافه بعد (ثوانٍ)',
  'settings.downloads.idleCommandTimeoutHint': 'كم يجوز للبرنامج أن يعمل قبل أن يُوقَف. والإيقاف ليس كالفشل: الأمر الذي ينيم جهازًا قد يُقتل في طريق النزول ويكون قد أدى عمله رغم ذلك.',
  'settings.downloads.idleCommandSecretHint': 'سطر الأمر مخزَّن نصًّا صريحًا في settings.json ويسافر مع كل نسخة احتياطية، فأبقِ كلمة المرور أو الرمز خارجه: ضعه في ملف لا يقرأه إلا البرنامج. وهو يبقى خارج حزمة التشخيص، ولا يُعرض من جديد في هذه الصفحة، ولهذا يكون الحقل أعلاه فارغًا بمجرد أن يكون شيء محفوظًا.',
  'settings.downloads.idleCommandStored': 'هناك أمر محفوظ ولا يُعرض هنا من جديد. اكتب شيئًا لاستبداله.',
  'settings.downloads.idleCommandStoredShort': 'الأمر المحفوظ',
  'settings.downloads.idleCommandVerify': 'قبل أن يفعله العد التنازلي',
  'settings.downloads.idleCommandVerifyHint': 'الفحص لا يفعل إلا أنه يحلّ مسار البرنامج ويقول ما خرج من ذلك، فالضغط عليه لا يكلّف شيئًا. أما التنفيذ فيفعل بالضبط ما سيفعله العد التنازلي، على هذه النسخة، وفورًا. وكلاهما يسأل عمّا هو محفوظ، فاحفظ الصفحة أولًا: ما دام هنا شيء غير محفوظ، يبقى الزران مطفأين.',
  'settings.downloads.idleCommandCheck': 'فحص الأمر',
  'settings.downloads.idleCommandChecking': 'جارٍ الفحص…',
