  'settings.downloads.idleCommandRun': 'تنفيذه الآن',
  'settings.downloads.idleCommandRunConfirm': 'بهذا يعمل {program} فورًا على هذه النسخة، تمامًا كما سيفعل العد التنازلي.',
  'settings.downloads.idleArmHint': 'إن حفظت هذه الصفحة والطابور خالٍ سلفًا، بدأ العد التنازلي فورًا. وهو لا ينتظر انتهاء الدفعة التالية.',
  'idleAction.action.quit': 'يتم الإنهاء',
