  'idleAction.problem.empty': 'لا برنامج مضبوط، فلا شيء يعمل. أدخل المسار الكامل للبرنامج في الأعلى.',
  'idleAction.problem.notFound': '{program} غير موجود على هذه النسخة.',
  'idleAction.problem.notFoundContainer': '{program} غير موجود داخل هذه الحاوية. وليس هنا إلا ما تجلبه الصورة: لا systemd، ولا curl، ولا ssh، ولا sudo. ضع الأمر على المضيف واستدعِه من هنا، أو أشِر هنا إلى سكربت ركّبته داخل الحاوية.',
  'idleAction.problem.notExecutable': '{path} موجود لكن لا يمكن تشغيله. اضبط صلاحية التنفيذ، واحرص على أن يستطيع المستخدم الذي تعمل تحته هذه العملية قراءته: في الحاوية هو uid 1000، لا root.',
  'idleAction.problem.permission': 'رفض النظام: هذه العملية غير مسموح لها بذلك. في الحاوية تعمل بـ uid 1000، بلا root وبلا أي وصول إلى المضيف، فكل ما يغيّر حالة الطاقة في الجهاز يجب أن يحدث على المضيف نفسه.',
  'idleAction.problem.timeout': 'كان البرنامج ما زال يعمل بعد {seconds} ثانية فأُوقف. ومن الوارد جدًا أنه أدى عمله رغم ذلك. ارفع الحد إن كان الأمر يحتاج وقتًا أطول.',
