  'idleAction.problem.suspendRefused': 'رفض النظام الإنامة. وعلى لينكس تكون إدارة الصلاحيات عادةً هي التي تريد تأكيدًا لا يستطيع هذا التطبيق إعطاءه: اسمح لمستخدمك بالإنامة، أو حوّل إلى «تنفيذ أمر» وأنِم الجهاز بسكربت خاص بك.',
