  'settings.transfer.title': 'الإعدادات فقط',
  'settings.transfer.hint': 'يكتب settings.json في ملف واحد: حدود الطابور، والمجلدات، ومجموعات القواعد، والفئات، والجدول الزمني. لا قائمة التنزيلات ولا السجل. والملف يحفظه متصفحك، وهو لا يذهب إلى أي مكان آخر.',
  'settings.transfer.export': 'تصدير الإعدادات',
  'settings.transfer.exportHint': 'يحفظ ملف .json واحدًا. استورده على الجهاز الجديد واختر هناك ما يُعتمد.',
  'settings.transfer.import': 'استيراد الإعدادات',
  'settings.transfer.importHint': 'لا يُكتب شيء قبل أن ترى القائمة وتؤكدها. ولا يتغير إلا ما تحدده أنت، وكل ما عداه يبقى كما هو هنا. ولا حاجة إلى إعادة تشغيل.',
  'settings.transfer.withSecrets': 'أخذ كلمات المرور المحفوظة معها',
  'settings.transfer.withSecretsHint': 'مشغّل: يحمل الملف كلمة مرور الموجّه، وكل كلمة مرور وكيل، وكل كلمة مرور أرشيف، نصًّا صريحًا. مطفأ: تصل هذه الحقول فارغة على الجهاز الآخر وتكتبها هناك مرة واحدة. وفي الحالتين قد يبقى سرّ واقفًا في مكان لا يعرفه أحد هنا: عنوان خلاصة فيه مفتاح API، أو كلمة مرور كتبتها في سكربت إعادة اتصال.',
  'settings.transfer.notTravellingLabel': 'ما لا يسافر أبدًا',
  'settings.transfer.notTravelling': 'ما لا يقف في هذا الملف أبدًا: بيانات دخولك إلى خدمات debrid والمستضيفين، وملفات الترويسات، ومفاتيح الكابتشا، وكلمة مرور الدخول إلى هذه الواجهة، وسكربتاتك. تلك تقيم معمّاة خارج settings.json، والأرشيف الكامل لا يحملها هو الآخر. تعيد إعدادها على الجهاز الجديد.',
