  'settings.transfer.group.other': 'كل ما تبقّى',
  'settings.mediahook.title': 'تنبيه مكتبة الوسائط',
  'settings.mediahook.hint': 'عنوان يستدعيه KnightLoader مرة واحدة، بمجرد أن تصل آخر ملفات الحزمة وتُنقل إلى مكانها. وهو مقصود لتحديث المكتبة في Jellyfin أو Plex، لكن الحقل لا يعرف عن أي منهما شيئًا: يستدعي العنوان الذي تكتبه، بالطريقة التي تختارها، ويضيف ترويسة واحدة إن أعطيته واحدة. وقيمة الترويسة تقيم معمّاة في المخزن نفسه الذي فيه بيانات دخول حساباتك، ولا تعود إلى هذه الصفحة أبدًا. ولا يُستدعى شيء إطلاقًا ما لم تخزّن عنوانًا وتختره عند درج في صفحة الفئات. والتنزيل الذي بلا اسم حزمة لا يطلق استدعاءً أبدًا، لأنه لا توجد حزمة يكون هو آخر ملف فيها. والحزمة التي تنتهي أثناء إعادة تشغيل الخادم لا يُستدعى لها هي الأخرى: الدورة الأولى تسجّل ما هو منتهٍ سلفًا دون أن تعلن عنه.',
  'settings.mediahook.empty': 'لا عنوان مخزَّن بعد.',
  'settings.mediahook.emptyHint': 'يستحق واحد العناء بمجرد أن يصير خادم الوسائط لديك لا يلاحظ الملفات الجديدة من تلقاء نفسه.',
  'settings.mediahook.add': 'إضافة عنوان',
  'settings.mediahook.name': 'الاسم',
  'settings.mediahook.nameHint': 'الاسم الذي تختار به هذا العنوان عند درج في صفحة الفئات. حروف وأرقام و- _ أو . فقط. ولا يمكن تغييره بعد ذلك، لأن الدرج يشير إليه بهذا الاسم.',
  'settings.mediahook.url': 'العنوان',
  'settings.mediahook.urlHint': 'العنوان الكامل الذي يُستدعى، http أو https، بالمضيف والمنفذ. اقرأه مرة أخرى قبل الحفظ: ما يقف هنا يُستدعى من هذا الجهاز. والعنوان نفسه مكتوب نصًّا صريحًا في settings.json ويسافر معها إلى حزمة التشخيص، فضع الرمز في الترويسة أدناه لا في جزء الاستعلام من العنوان.',
  'settings.mediahook.method': 'الطريقة',
  'settings.mediahook.methodHint': 'GET أو POST. ويُرسل POST بلا محتوى. وJellyfin يريد POST، وPlex يريد GET، وإن كنت غير متأكد فالاستدعاء التجريبي يقول لك ما تقبله الجهة المقابلة.',
  'settings.mediahook.headerName': 'اسم الترويسة',
  'settings.mediahook.headerNameHint': 'الترويسة الوحيدة التي تُرسل مع الاستدعاء، مثل X-Emby-Token عند Jellyfin. اتركها فارغة فلا تُرسل ترويسة إضافية.',
  'settings.mediahook.headerValue': 'قيمة الترويسة',
  'settings.mediahook.headerValueHint': 'الرمز الذي يدخل في تلك الترويسة. وهو يقيم معمّى في المخزن نفسه الذي فيه بيانات دخول حساباتك، ولا يُكتب في settings.json أبدًا، ولا يُرسل إلى هذه الصفحة أبدًا.',
  'settings.mediahook.valueStored': 'محفوظة',
  'settings.mediahook.valueStoredHint': 'تبقى القيمة على هذه النسخة. اترك الحقل كما هو للإبقاء عليها، أو اكتب واحدة جديدة لاستبدالها. وإن أفرغت الحقل ذهبت القيمة.',
  'settings.mediahook.goesTo': 'الاستدعاء يذهب إلى {host}',
  'settings.mediahook.goesToForeign': 'هذا العنوان ليس في شبكتك أنت. الاستدعاء يغادر هذا الجهاز، والترويسة تذهب معه.',
  'settings.mediahook.wait': 'الانتظار قبل الاستدعاء',
  'settings.mediahook.waitHint': 'كم يُترك هذا العنوان في حاله بعد انتهاء حزمة، حتى تصير عشرون حزمة تنتهي معًا استدعاءً واحدًا بدل عشرين. فحص المكتبة يكلّف خادم الوسائط عملًا حقيقيًا، والفحص الذي يصل بعد دقيقة لا يكلّفك شيئًا. وعلى 0 يخرج الاستدعاء بمجرد أن تستقر ملفات الحزمة في مكانها، دون انتظار المزيد.',
