  'settings.nav.health': 'الحالة',
  'settings.module.metrics': 'عنوان المقاييس لنظام مراقبة',
  'settings.health.title': 'الحالة الآن',
  'settings.health.titleHint': 'هذه الصفحة تقرأ فقط. لا شيء عليها يبدأ أو يوقف أو يغيّر شيئًا، وتركها مفتوحة لا يغيّر شيئًا هو الآخر. والأرقام تُجلب كل عشر ثوانٍ، والجلب الفاشل يترك آخر قراءة واقفة بدل أن تفرغ الصفحة. والأجزاء التي لا بد من استقصائها تُشارَك نصف دقيقة، فما يقف هنا قد يتأخر حتى ثلاثين ثانية عن الصفوف في صفحة التنزيلات.',
  'settings.health.version': 'الإصدار',
  'settings.health.uptime': 'يعمل منذ',
  'settings.health.uptimeHint': 'منذ متى تعمل هذه العملية، لا منذ متى يعمل الجهاز. والحاوية التي أُعيد تشغيلها قبل ساعة تبدأ هنا من الصفر من جديد، مهما قال المضيف. والتاريخ بجوارها هو ساعة الخادم نفسه، لا ساعة متصفحك.',
  'settings.health.startedAt': 'بدأ',
  'settings.health.sampled': 'قُرئ قبل {n} ثانية',
  'settings.health.loadFailed': 'تعذّر تحميل الحالة. هل الخادم متاح؟',
  'settings.health.oldHealthHint': 'العنوان القديم /api/health لم يتغير، وهو يجيب بـ«ok» ما دامت هذه العملية تعمل، مهما قالت هذه الصفحة. وهذا مقصود: فحص سلامة الحاوية نفسها، وجسر Click\'n\'Load، وبحث تطبيق الهاتف عن النُسخ في شبكتك، كلها تقرأه، وأي جواب غير «ok» هناك كان سيُعلّم الحاوية غير سليمة ويجعل الهاتف يكفّ عن إيجاد هذه النسخة. والخلل يُبلَّغ عنه في هذه الصفحة. أما ذلك العنوان فلا يقول إلا إن كان هناك من ينصت أصلًا.',
  'health.state.ok': 'يعمل',
  'health.state.degraded': 'يعمل، لكن به خلل',
  'health.state.failed': 'لا يعمل',
  'health.state.unused': 'غير مستخدم هنا',
