  'settings.health.partsHint': 'صف لكل مكوّن من التطبيق يمكن أن يعطب وحده. والمكوّن الذي لم تُعدّه قط على هذه النسخة يقول ذلك بدل أن يُعدّ خللًا، والمكوّن الذي لا يستطيع هذا البناء سؤاله يقول ذلك هو الآخر، وهذا جواب ثالث لا صفر صامت. وقراءة الصف لا تغيّر شيئًا: المكوّن الذي يقول إنه لا يعمل معطّل منذ فترة، وهنا تعرف ذلك فقط.',
