  'health.part.captcha': 'كابتشا',
  'health.remedy.store.failed': 'لم تجب قاعدة البيانات. التنزيلات تواصل عملها، لكن لم يعد يُكتب عنها شيء، فإعادة التشغيل ستفقد كل ما تغيّر منذ ذلك الحين. تحقق من أن مجلد البيانات ما زال مركّبًا وما زال قابلًا للكتابة.',
  'health.remedy.jd.unreachable': 'KL_JD يسمّي عنوانًا لا تصل إليه هذه النسخة الآن. تحقق من أن حاوية JDownloader تعمل، ومن أن منفذ API الخاص بها يجيب من هنا. والروابط التي لا يجلبها إلا JDownloader تبقى في الطابور حتى ذلك الحين، وهي لم تفشل.',
  'health.remedy.jd.notWired': 'JDownloader يجيب من جديد، لكن هذه العملية وصّلت خلفياتها عند البدء ولم يكن موجودًا حينها. أعد تشغيل KnightLoader ليُؤخذ في الحسبان.',
  'health.remedy.ytdlp.missing': 'لم يُعثر على yt-dlp عند بدء هذه العملية (KL_YTDLP، أو «yt-dlp» في PATH). وعندها تفشل صفحات الوسائط بخطأ الموقع نفسه، بدل أن تُفتح إلى صيغ مختلفة. وليُعثر عليه لا بد من إعادة تشغيل.',
  'health.remedy.disk.low': 'مجلد وجهة تحت الحد الذي ضبطته في صفحة التنزيلات. ولا يبدأ هناك شيء جديد حتى يتوفر متسع من جديد، أو حتى تخفض الحد. وما يعمل سلفًا لا يوقفه هذا الحد.',
  'health.remedy.disk.elsewhere': 'مجلد غير موجود، ولذلك تصف الأرقام أقرب مجلد فوقه. وإن كان تركيب لم يرتفع، فذلك قرص مختلف تمامًا. انظر إلى المسار قبل أن تصدّق الأرقام.',
  'health.remedy.accounts.benched': 'حساب مستضيف واحد على الأقل يُترك في حاله بعد خطأ. ويُجرَّب من تلقاء نفسه مرة أخرى حين تنقضي مدة الانتظار، ومدة الانتظار تتضاعف في كل مرة. افتح الحسابات واضغط تحديث عند الصف إن أردت أن تعرف الآن.',
  'health.remedy.accounts.invalid': 'رُفض حساب مستضيف واحد على الأقل. مفتاح جديد أو اشتراك مجدَّد يصلح ذلك، أما الانتظار فلا.',
  'health.remedy.feeds.failing': 'فشل آخر جلب لاشتراك واحد على الأقل. وأيّها ولماذا مكتوب في صفحة التنزيلات بجوار الخلاصة، وفي سطور السجل في صفحة التشخيص.',
  'health.remedy.relay.down': 'هناك عنوان مُرحِّل مخزَّن والاتصال غير قائم. وهذه النسخة تواصل المحاولة من تلقاء نفسها، وكل شيء محلي يعمل كالعادة؛ الوصول إليها من الخارج وحده هو ما لا يعمل.',
  'health.remedy.captcha.waiting': 'خلفية توقفت لتسأل إنسانًا. ولا يتحرك شيء خلفها حتى يجيب أحد.',
  'settings.health.tasks': 'التنزيلات الآن',
  'settings.health.tasksHint': 'لقطة للقائمة كما هي، لا عدّاد عبر الزمن. و«فشل» يعدّ الصفوف الواقفة الآن في القائمة وعليها خطأ، فالرقم ينزل حين تزيلها وحين تُرتَّب القائمة بعد الأيام التي ضبطتها، ويصعد من جديد حين يقع خطأ جديد. ولا شيء هنا معدّل، ولا شيء هنا يقول كم مرة فشل شيء ما.',
