  'settings.health.scrape': 'المراقبة',
  'settings.health.scrapeSwitch': 'الإجابة على عنوان المقاييس',
  'settings.health.scrapeHint': 'يفتح عنوانًا ثانيًا يعطي الأرقام نفسها نصًّا صريحًا، بالصيغة التي يقرؤها Prometheus والأدوات المبنية على شاكلته. وهو يُجلب ولا يُرسل أبدًا: لا يغادر هذا الجهاز شيء ما لم تأتِ مراقبتك أنت إلى هنا وتطلبه. وما دام هذا مطفأً فالعنوان غير موجود أصلًا ويجيب بالرمز 404، كأي عنوان لا يملكه هذا التطبيق. وعلى نسخة لها كلمة مرور يحتاج الجلب إلى واحد من رموز API عندك، وكل جامع يمكن تعليمه أن يرسل واحدًا. والجامع لا يرسل ترويسة أصل، فيمرّ؛ أما تبويب متصفح على عنوان آخر فيرسلها، ويُرفض إن لم تطابق عنوان هذه النسخة نفسه. والنص يحمل مسارات مجلدات وجهتك، فضعه حيث تضع أسماء المجلدات نفسها.',
