  'settings.owner.envHow': 'لتعمل تحت حساب آخر، سمِّه في أمر التشغيل: --user <uid>:<gid>. وعلى Unraid يوضع ذلك في Extra Parameters، ولا بد من إعادة إنشاء الحاوية ليصير ساريًا.',
