  'settings.owner.checkHint': 'هنا يُكتب فعلًا ملف واحد ومجلد فرعي واحد في كل مجلد، ثم يُقرأ مَن يملكهما ومَن غيره يجوز له أن يقرأهما، ثم يُزال الاثنان من جديد. ولا بد من قياس ذلك بدل حسابه: المشاركة قد تحمل قواعد أذونات خاصة بها، والمجلد الموسوم بـ set-group-id يمنح مجموعة غير التي تحملها هذه العملية. والفحص يعمل من تلقاء نفسه بعد أن تحفظ مجلدًا غيّرته، وكلما ضغطت الزر.',
