  'settings.diagnostics.fix.utcFallback': 'المتغيّر TZ مضبوط على {subject}، ولم تستطع هذه النسخة تحميل تلك المنطقة، فارتدت إلى UTC دون أن تقول ذلك في أي مكان. وكل نافذة جدول زمني تعمل على UTC حتى يُصلَح هذا. تحقق من الكتابة مقابل قائمة المناطق («Europe/Berlin»)، ومن أن الصورة تحمل قاعدة بيانات مناطق أصلًا.',
