  'settings.resolvers.toolsYtdlpMissingHint': 'بلا yt-dlp لا توجد خلفية وسائط إطلاقًا: الرابط إلى صفحة فيديو يُرفض بخطأ الموقع نفسه بدل أن يُنزَّل. وفي الحاوية يأتي من حزمة yt-dlp التي في الصورة؛ وعلى سطح المكتب تثبّته بنفسك وتضعه إما في PATH وإما تجعل KL_YTDLP يشير إليه. والزر أدناه يجلب نسخة خاصة من تلقاء نفسه إن لم يكن أيّ منهما ممكنًا.',
  'settings.resolvers.toolsFfmpegMissingHint': 'بلا ffmpeg لا يستطيع yt-dlp أن يضم مسارَي الصورة والصوت المنفصلين اللذين تسلّمهما أكثر المواقع، فيحطّ التنزيل مسار فيديو صامتًا أو يفشل تمامًا. وبلا ffprobe لا يقيس «قياس الملف بعد انتهائه» أعلى هذه الصفحة شيئًا ولا يقول عنه شيئًا. وفي الحاوية يأتي الاثنان من حزمة ffmpeg التي تثبّتها الصورة؛ وعلى سطح المكتب تثبّتهما بنفسك وتضعهما في PATH.',
